mapper.select:
SELECT , IFNULL(i.issue_total, 0) AS issue_total, IFNULL(i.issue_completed, 0) AS issue_completed, IFNULL(e.evidence_total, 0) AS evidence_total, IFNULL(e.evidence_confirmed, 0) AS evidence_confirmed FROM audit_project p
p.deleted = 0
AND (p.project_name LIKE CONCAT('%', #{q.keyword}, '%') OR p.project_code LIKE CONCAT('%', #{q.keyword}, '%') OR p.audited_unit LIKE CONCAT('%', #{q.keyword}, '%'))
AND p.status = #{q.status}
AND p.audit_type = #{q.auditType}
AND p.risk_level = #{q.riskLevel}
AND p.audited_unit LIKE CONCAT('%', #{q.auditedUnit}, '%')
AND p.start_date >= #{q.beginDate}
AND p.start_date <= #{q.endDate}
ORDER BY p.create_time DESC
